import{_ as a,o as i,c as l,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"Ceph Testing Meeting 2018-10-10","description":"","frontmatter":{"title":"Ceph Testing Meeting 2018-10-10","date":"2018-10-10T00:00:00.000Z","updated":"2018-10-18T00:00:00.000Z","tags":["Ceph","分布式存储","CRUSH 算法","高可用性","可扩展性","对象存储","块存储","文件系统存储","一致性","去中心化"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2018/Ceph_Testing_Meeting_2018-10-10.md","filePath":"posts/2018/Ceph_Testing_Meeting_2018-10-10.md","lastUpdated":1780460162000}'),r={name:"posts/2018/Ceph_Testing_Meeting_2018-10-10.md"};function o(n,e,h,s,p,d){return i(),l("div",null,[...e[0]||(e[0]=[t('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议时间" tabindex="-1">会议时间： <a class="header-anchor" href="#会议时间" aria-label="Permalink to &quot;会议时间：&quot;">​</a></h4><p>[请填写会议时间]</p><h4 id="参会人员" tabindex="-1">参会人员： <a class="header-anchor" href="#参会人员" aria-label="Permalink to &quot;参会人员：&quot;">​</a></h4><p>[请填写参会人员名单]</p><h4 id="会议主题" tabindex="-1">会议主题： <a class="header-anchor" href="#会议主题" aria-label="Permalink to &quot;会议主题：&quot;">​</a></h4><p>Ceph存储系统及视频会议字幕翻译相关议题讨论</p><h4 id="关键细节" tabindex="-1">关键细节： <a class="header-anchor" href="#关键细节" aria-label="Permalink to &quot;关键细节：&quot;">​</a></h4><ol><li><p><strong>Ceph存储系统更新</strong>：</p><ul><li>Nathan不在，Zack可能需要会议。</li><li>发现两个新的PRS列表项，一个关于打包，另一个是关于 cherry-picks 的，涉及Loic和Nathan的工作，但仅用于测试仓库。</li><li>讨论了 cherry-picks 的功能，它是一个扩展安装任务，允许在配置目标后选择性使用repose，目前仅支持zipper。</li><li>强调了该功能不应影响代码的其他部分，主要是针对openSUSE的。</li></ul></li><li><p><strong>文件系统问题</strong>：</p><ul><li>讨论了Ceph文件系统在13.2版本中的问题，并计划在未来一周或两周内进一步讨论。</li><li>提出了使用sahaba corpus encode和decode来防止此类问题的可能性。</li></ul></li><li><p><strong>视频会议字幕翻译</strong>：</p><ul><li>讨论了subsea的更改，可以继续进行工作。</li><li>计划部署测试实例，并在Voyager上运行一些示例任务。</li><li>提出了关于病理日志的问题，特别是关于如何隐藏敏感信息。</li><li>讨论了在部署过程中可能暴露敏感变量的情况，并建议在echo环境变量时使用grep来过滤敏感变量。</li></ul></li></ol><h4 id="讨论的主要议题" tabindex="-1">讨论的主要议题： <a class="header-anchor" href="#讨论的主要议题" aria-label="Permalink to &quot;讨论的主要议题：&quot;">​</a></h4><ul><li>cherry-picks的功能和适用性</li><li>Ceph文件系统的问题和解决方案</li><li>视频会议字幕翻译中的敏感信息保护</li></ul><h4 id="决定的事项" tabindex="-1">决定的事项： <a class="header-anchor" href="#决定的事项" aria-label="Permalink to &quot;决定的事项：&quot;">​</a></h4><ul><li>进一步调查和讨论Ceph文件系统的问题。</li><li>Nginx和OpenStack CLI的使用，特别是关于敏感信息保护。</li><li>检查openSUSE和上游代码，以确定敏感信息暴露的位置。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划： <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划：&quot;">​</a></h4><ul><li>[负责人] 将调查Ceph文件系统的问题，并准备下周的讨论。</li><li>[负责人] 将查找有关openSUSE和上游代码的信息，以确定敏感信息暴露的位置。</li><li>[负责人] 将尝试部署测试实例，并测试病理日志的敏感性。</li></ul><h4 id="其他事项" tabindex="-1">其他事项： <a class="header-anchor" href="#其他事项" aria-label="Permalink to &quot;其他事项：&quot;">​</a></h4><ul><li>[请填写其他需要记录的事项]</li></ul><p>[会议结束]</p>',18)])])}const _=a(r,[["render",o]]);export{u as __pageData,_ as default};
